package io.github.jasper.monitoring.api.management.command;
import java.util.Objects;
public final class AlertAcknowledgeCommand { private final String alertId,reason,idempotencyKey; private final long expectedVersion; private AlertAcknowledgeCommand(String id,long version,String reason,String key){if(version<1)throw new IllegalArgumentException("expectedVersion must be positive");this.alertId=bounded(id,256);this.reason=bounded(reason,512);this.idempotencyKey=bounded(key,128);this.expectedVersion=version;} public static AlertAcknowledgeCommand of(String id,long version,String reason,String key){return new AlertAcknowledgeCommand(id,version,reason,key);} public String getAlertId(){return alertId;} public long getExpectedVersion(){return expectedVersion;} public String getReason(){return reason;} public String getIdempotencyKey(){return idempotencyKey;} private static String bounded(String s,int max){Objects.requireNonNull(s);if(s.trim().isEmpty()||s.length()>max)throw new IllegalArgumentException("value is blank or too long");return s;} }
